# File generated by generate_dom_and.py

from verif_msi import *

import os
import sys

order = 3
prop = 'pini'
withGlitches = False
dumpCirc = False
checkFunctionality = False
circuitFilename = 'circuit.dot'


def usage():
    print('Usage: %s [options]' % os.path.basename(__file__))
    print('   This script contains a VerifMSI description of a circuit implementing the logical AND following the DOM scheme with 4 shares.')
    print('   This file was generated using the script generate_dom_and.py')
    print('Options:')
    print('-o,  --order <n>            : Set the order of the verification to (default: %d)' % order)
    print('-p,  --prop                 : Set security property to verify: either \'ni\' (Non-Interference), \'sni\' (Strong Non-Interference) \'rni\' (Relaxed Non-Interference) or \'tps\' (Treshold Probing Security). NI and SNI use a share description for the inputs, while TPS uses a secrets + masks description (default: %s)' % prop)
    print('-g,  --with-glitches        : Consider glitch propagation throughout gates (defaut: %s)' % (withGlitches and 'Yes' or 'No'))
    print('-ng, --without-glitches     : Do not consider glitch propagation throughout gates (defaut: %s)' % (withGlitches and 'No' or 'Yes'))
    print('-d, --dump-circuit          : Dump the circuit in dot format in a file named \'%s\' (default: %r)' % (circuitFilename, dumpCircuit))
    print('-c, --check-functionality   : Check the circuit functionality via exhaustive evaluation (default: %r)' % checkFunctionality)


def test_pini_0(*argv):
    global order
    global prop
    global withGlitches
    global dumpCirc
    global checkFunctionality

    idx = 0
    while idx < len(argv):
        arg = argv[idx]
        if arg == '-h' or arg == '--help':
            usage()
            sys.exit(0)
        elif arg == '-o' or arg == '--order':
            idx += 1
            order = int(argv[idx])
        elif arg == '-p' or arg == '--prop':
            idx += 1
            prop = argv[idx]
        elif arg == '-g' or arg == '--with-glitches':
            withGlitches = True
        elif arg == '-ng' or arg == '--without-glitches':
            withGlitches = False
        elif arg == '-d' or arg == '--dump-circuit':
            dumpCirc = True
        elif arg == '-c' or arg == '--check-functionality':
            checkFunctionality = True
        else:
            print('*** Error: unrecognized option: %s' % arg, file = sys.stderr)
            usage()
            sys.exit(1)
        idx += 1
    
    
    if order >= 4:
        print('*** Error: the order of verification (%d) must be less than the number of shares (4)' % (order))
        sys.exit(1)
    
    if prop != 'ni' and prop != 'sni' and prop != 'tps' and prop != 'rni' and prop != 'pini':
        print('*** Error: Unknown security property: %s' % prop)
        print('    Valid values are: \'ni\' (Non-Interference), \'sni\' (Strong Non-Interference), \'rni\' (Relaxed Non-Interference) and \'tps\' (Treshold Probing Security)')
        sys.exit(1)
    

    a = symbol('a', 'S', 1)
    b = symbol('b', 'S', 1)

    if prop == 'tps':
        a0, a1, a2, a3 = getPseudoShares(a, 4)
        b0, b1, b2, b3 = getPseudoShares(b, 4)
    else:
        a0, a1, a2, a3 = getRealShares(a, 4)
        b0, b1, b2, b3 = getRealShares(b, 4)

    a0 = inputGate(a0)
    a1 = inputGate(a1)
    a2 = inputGate(a2)
    a3 = inputGate(a3)
    b0 = inputGate(b0)
    b1 = inputGate(b1)
    b2 = inputGate(b2)
    b3 = inputGate(b3)

    f0 = andGate(a0, a1, a2)
    f1 = andGate(a0, a1, a2)
    #a0b1 = andGate(a0, b1)
    #a0b2 = andGate(a0, b2)
    #a0b3 = andGate(a0, b3)
    #a1b0 = andGate(a1, b0)
    #a1b1 = andGate(a1, b1)
    #a1b2 = andGate(a1, b2)
    #a1b3 = andGate(a1, b3)
    #a2b0 = andGate(a2, b0)
    #a2b1 = andGate(a2, b1)
    #a2b2 = andGate(a2, b2)
    #a2b3 = andGate(a2, b3)
    #a3b0 = andGate(a3, b0)
    #a3b1 = andGate(a3, b1)
    #a3b2 = andGate(a3, b2)
    #a3b3 = andGate(a3, b3)

    u0 = andGate(a0, a1, a2)
    u1 = andGate(a0, a1, a2)
    u2 = andGate(a0, a1, a2)
    u3 = a3

    v0 = andGate(a0, a1, a2)
    v1 = andGate(a0, a1, a2)
    v2 = andGate(a0, a1, a2)
    v3 = a3


    nbLeak, nbCheck = checkSecurity(order, withGlitches, prop, [u0, u1, u2, u3], [v0, v1, v2, v3])
    return nbLeak, nbCheck



if __name__ == '__main__':
    nbLeak, nbCheck = test_pini_0(*sys.argv[1:])
    print('# Total Nb. of expressions analysed: %d' % nbCheck)
    print('# Total Nb. of potential leakages found: %d' % nbLeak)
    assert nbLeak == 3
    assert nbCheck == 4

